/* option-explorer shell: builds the panel and the frame, loads the screens,
   and draws the chosen option. Projects do not edit this file.

   Screens live in prototype/screens/<name>.js, listed in SCREEN_FILES in the
   prototype's HTML, and register themselves with defineScreen(). Each screen:

   defineScreen('home', {
     name: 'Home',
     controls: [{ key:'sheet', label:'Sheet height', note:'optional line',
                  options:[['medium','Medium'], ['large','Large']] }],   // optional
     options: {
       A: { name, claim, status: 'exploring' | 'chosen' | 'notchosen',
            render(v),          // the mobile screen's HTML; v = {desktop, ...control values}
            renderDesktop(v),   // optional, only when there is a desktop design
            after(body, v),     // optional, wire up taps once the HTML is in place
            readout,            // optional [{l, v, s}] or (body, v) => rows, measured values only
            notes,              // optional [[title, detail]], numbered to match mk(n)
            questions }         // optional ['open question']
     }
   });

   Helpers for screens: mk(n) places annotation marker n, ph() a placeholder
   block, OE.set(key, value) changes a control and redraws.

   Frozen copies (explorations/) are bundled into one file by freeze.py, which
   sets window.OE_BUNDLED, inlines every screen and calls OE.start(). */
(function () {
  'use strict';
  const SCREENS = {};
  const STATUS = {chosen:'Chosen', notchosen:'Not chosen', exploring:'Exploring'};
  const failed = [];
  const $ = s => document.querySelector(s);
  const esc = t => String(t == null ? '' : t).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

  window.defineScreen = (key, def) => { SCREENS[key] = def; };
  window.mk = n => `<span class="mk" aria-hidden="true">${n}</span>`;
  window.ph = (t, s, n, cls = '') => `<div class="ph ${cls}">${n ? window.mk(n) : ''}<b>${t}</b>${s || ''}</div>`;

  const MARKUP = `
<button class="railtoggle" id="railToggle" aria-expanded="false">Controls</button>
<div class="lab">
  <aside class="rail" id="rail">
    <div class="railtop">
      <div class="row">
        <div class="chips" id="cDevice" role="group" aria-label="Device">
          <button class="chip" data-device="mobile">Mobile</button>
          <button class="chip" data-device="desktop">Desktop</button>
        </div>
        <button class="chip" id="cAnnot">Annotations</button>
        <button class="railclose" id="railClose" aria-label="Close controls">✕</button>
      </div>
      <button class="tolink" id="toNotes">Notes for the markers are at the bottom ↓</button>
    </div>
    <div class="railbody">
      <div class="railhead">
        <h1 id="pTitle"></h1>
        <p class="sub" id="pSub"></p>
        <a class="hist" id="pHist" href="explorations/index.html">Every iteration →</a>
      </div>
      <div class="grp"><h2>Screens</h2><div class="opts" id="cScreens"></div></div>
      <div class="grp"><h2>Options</h2><div class="opts" id="cOpts"></div></div>
      <div id="cCtrl"></div>
      <div class="grp" id="gReadout"><h2>Readout</h2><div class="readout" id="readout"></div>
        <p class="note">Measured values only. Anything asserted belongs in the notes.</p></div>
      <div class="grp" id="gQs"><h2>Questions</h2><ol class="qs" id="qs"></ol></div>
      <div class="grp" id="gNotes"><h2>Notes</h2><ol class="nlist" id="notes"></ol>
        <p class="note">Numbers match the markers on the screen. Turn them off with Annotations at the top.</p></div>
    </div>
  </aside>
  <main class="stage">
    <div class="stagehead"><span class="scr" id="scrName"></span><h2 id="optName"></h2><p id="optClaim"></p></div>
    <p class="loaderr" id="loadErr" hidden></p>
    <div class="device">
      <div class="chrome" aria-hidden="true"><span class="cdots"><i></i><i></i><i></i></span><span class="curl">example.com</span></div>
      <div class="screen"><div class="body" id="body"></div></div>
    </div>
    <p class="devnote" id="devNote" hidden>No desktop layout for this option yet, so this is the mobile screen.</p>
  </main>
</div>`;

  // Load screen files one after another, so they register in SCREEN_FILES order.
  function load(files, done) {
    let i = 0;
    const next = () => {
      if (i >= files.length) return done();
      const s = document.createElement('script');
      s.src = 'prototype/screens/' + files[i++] + '.js';
      s.onload = next;
      s.onerror = () => { failed.push(s.getAttribute('src')); next(); };
      document.body.appendChild(s);
    };
    next();
  }

  function start() {
    // PROJECT and SCREEN_FILES are top-level consts in the prototype's HTML, so read them by name.
    const P = (typeof PROJECT !== 'undefined' && PROJECT) || {title:'Prototype', sub:''};
    $('#pTitle').textContent = P.title;
    $('#pSub').textContent = P.sub || '';
    if (location.pathname.includes('/explorations/')) $('#pHist').hidden = true; // a frozen copy
    if (failed.length) {
      $('#loadErr').hidden = false;
      $('#loadErr').textContent = 'Could not load ' + failed.join(', ') + '. Check the name in SCREEN_FILES matches the file.';
    }
    const keys = Object.keys(SCREENS);
    if (!keys.length) { $('#body').innerHTML = ''; return; }

    // State: URL first (frozen copies and links open where they were), then what you last looked at.
    const KEY = 'oe:' + location.pathname;
    const store = { get(){ try { return JSON.parse(localStorage.getItem(KEY)) || {} } catch (e) { return {} } },
                    set(v){ try { localStorage.setItem(KEY, JSON.stringify(v)) } catch (e) {} } };
    const q = new URLSearchParams(location.search), saved = store.get();
    let screen = SCREENS[q.get('screen')] ? q.get('screen') : (SCREENS[saved.screen] ? saved.screen : keys[0]);
    const opt = {}, ctrl = {};
    keys.forEach(s => {
      const o = (saved.opt || {})[s];
      opt[s] = SCREENS[s].options[o] ? o : Object.keys(SCREENS[s].options)[0];
      ctrl[s] = {};
      (SCREENS[s].controls || []).forEach(c => {
        const v = ((saved.ctrl || {})[s] || {})[c.key];
        ctrl[s][c.key] = c.options.some(x => x[0] === v) ? v : c.options[0][0];
      });
    });
    if (q.get('option') && SCREENS[screen].options[q.get('option')]) opt[screen] = q.get('option');
    (SCREENS[screen].controls || []).forEach(c => { if (q.has(c.key)) ctrl[screen][c.key] = q.get(c.key); });
    let device = q.get('device') || saved.device || 'mobile';
    let annot = q.has('annot') ? q.get('annot') !== '0' : saved.annot !== false;
    const remember = () => store.set({screen, opt, ctrl, device, annot});

    function draw() {
      const S = SCREENS[screen], o = S.options[opt[screen]];
      $('#cScreens').innerHTML = keys.map(k => {
        const n = Object.keys(SCREENS[k].options).length;
        return `<button class="opt" data-s="${k}" aria-pressed="${k === screen}"><b>${esc(SCREENS[k].name)}</b><span>${n} option${n > 1 ? 's' : ''}</span></button>`;
      }).join('');
      $('#cOpts').innerHTML = Object.entries(S.options).map(([k, v]) =>
        `<button class="opt" data-k="${k}" aria-pressed="${k === opt[screen]}"><b>${esc(v.name)}<span class="stat ${v.status}">${STATUS[v.status] || esc(v.status)}</span></b><span>${esc(v.claim)}</span></button>`).join('');
      $('#cCtrl').innerHTML = (S.controls || []).map(c =>
        `<div class="grp"><h2>${esc(c.label)}</h2><div class="chips" data-ctrl="${c.key}">` +
        c.options.map(([val, label]) => `<button class="chip" data-v="${esc(val)}" aria-pressed="${ctrl[screen][c.key] === val}">${esc(label)}</button>`).join('') +
        `</div>${c.note ? `<p class="note">${esc(c.note)}</p>` : ''}</div>`).join('');
      $('#scrName').textContent = S.name;
      $('#optName').textContent = o.name;
      $('#optClaim').textContent = o.claim || '';
      const qs = o.questions || [];
      $('#gQs').hidden = !qs.length;
      $('#qs').innerHTML = qs.map(x => `<li>${esc(x)}</li>`).join('');
      const notes = o.notes || [];
      $('#gNotes').hidden = !annot || !notes.length;
      $('#toNotes').hidden = !annot || !notes.length;
      $('#notes').innerHTML = notes.map((n, i) =>
        `<li><span class="n">${i + 1}</span><span><b>${esc(n[0])}</b>${n[1] ? '<br>' + esc(n[1]) : ''}</span></li>`).join('');

      // Desktop only takes effect above 1000px; without renderDesktop the phone screen keeps its width.
      const desk = device === 'desktop' && matchMedia('(min-width:1001px)').matches;
      const mobileOnly = desk && !o.renderDesktop;
      $('.device').classList.toggle('mobile-only', mobileOnly);
      $('#devNote').hidden = !mobileOnly;
      document.body.classList.toggle('desktop', device === 'desktop');
      document.body.classList.toggle('annot', annot);
      document.querySelectorAll('#cDevice .chip').forEach(c => c.setAttribute('aria-pressed', String(c.dataset.device === device)));
      $('#cAnnot').setAttribute('aria-pressed', String(annot));

      const v = Object.assign({desktop: desk && !!o.renderDesktop}, ctrl[screen]);
      const body = $('#body');
      body.innerHTML = (desk && o.renderDesktop) ? o.renderDesktop(v) : o.render(v);
      body.scrollTop = 0;
      if (o.after) o.after(body, v);
      const fill = rows => {
        $('#gReadout').hidden = !rows.length;
        $('#readout').innerHTML = rows.map(r =>
          `<div class="rrow"><span class="rl">${esc(r.l)}</span><span class="rv">${esc(r.v)}</span><span class="rs">${esc(r.s || '')}</span></div>`).join('');
      };
      if (typeof o.readout === 'function') { fill([]); requestAnimationFrame(() => fill(o.readout(body, v) || [])); }
      else fill(o.readout || []);
    }

    window.OE.set = (key, value) => { ctrl[screen][key] = value; remember(); draw(); };
    window.OE.redraw = draw;
    $('#cScreens').addEventListener('click', e => { const b = e.target.closest('.opt'); if (!b) return; screen = b.dataset.s; remember(); draw(); });
    $('#cOpts').addEventListener('click', e => { const b = e.target.closest('.opt'); if (!b) return; opt[screen] = b.dataset.k; remember(); draw(); });
    $('#cCtrl').addEventListener('click', e => {
      const b = e.target.closest('.chip'); if (!b) return;
      ctrl[screen][b.parentElement.dataset.ctrl] = b.dataset.v; remember(); draw();
    });
    $('#cDevice').addEventListener('click', e => { const b = e.target.closest('.chip'); if (!b) return; device = b.dataset.device; remember(); draw(); });
    $('#cAnnot').addEventListener('click', () => { annot = !annot; remember(); draw(); });
    // Scroll the rail only, never the page (scrollIntoView would move the stage too).
    $('#toNotes').addEventListener('click', () => {
      const rail = $('#rail'), top = $('.railtop').offsetHeight;
      rail.scrollTo({top: rail.scrollTop + $('#gNotes').getBoundingClientRect().top - rail.getBoundingClientRect().top - top - 12, behavior:'smooth'});
    });
    matchMedia('(min-width:1001px)').addEventListener('change', draw);
    const setRail = open => { document.body.classList.toggle('railopen', open); $('#railToggle').setAttribute('aria-expanded', open); };
    $('#railToggle').addEventListener('click', () => setRail(true));
    $('#railClose').addEventListener('click', () => setRail(false));
    draw();
  }

  window.OE = { start };
  document.body.insertAdjacentHTML('afterbegin', MARKUP);
  if (!window.OE_BUNDLED) load((typeof SCREEN_FILES !== 'undefined' && SCREEN_FILES) || [], start);
})();
